Form.parameter:
function adjustPoolSize(mm) {
	min = 0;
	max = 0;
	try {
		s1 = form.getConfig("minPoolSize")
		if (s1 != null && s1.length() > 0) {
			min = java.lang.Integer.parseInt(s1);
		}
	} catch(ign) {
		form.setConfig("minPoolSize", "0");
		form.updateControl("minPoolSize");
		form.alert(ign.toString());
		return;
	}

	try {
		s2 = form.getConfig("maxPoolSize")
		if (s2 != null && s2.length() > 0) {
			max = java.lang.Integer.parseInt(s2);
		}
	} catch(ign) {
		form.setConfig("maxPoolSize", s1);
		form.updateControl("maxPoolSize");
		form.alert(ign.toString());
		return;
	}

	if(min > max) {
		if(mm) {
			form.setConfig("maxPoolSize", s1);
			form.updateControl("maxPoolSize");
		} else {
			form.setConfig("minPoolSize", s2);
			form.updateControl("minPoolSize");
		}
	}
}
function maxPoolSize_focusout() {
	adjustPoolSize(false);
}
function minPoolSize_focusout() {
	adjustPoolSize(true);
}
function initializeAttempts_changed() {
	str = form.getConfig("initializeSleepInterval");
	if(str == null || str.equals("")) {
		form.setConfig("initializeSleepInterval", "10");
		form.updateControl("initializeSleepInterval");
	}
}

function enabled_changed () {
