var enable = false;
if ( val != null &&
val.equalsIgnoreCase ("true") ) enable = true;
form.getControl ("minPoolSize").setEnabled (enable);
form.getControl ("maxPoolSize").setEnabled (enable);
form.getControl ("purgeInterval").setEnabled (enable);
form.getControl ("initializeAttempts").setEnabled (enable);
