function changeDetectionMode_changed () {
	var value = form.getConfigValue ("changeDetectionMode");
	var enable = !value.equalsIgnoreCase(Packages.com.ibm.di.fc.DeltaFC.PARAM_DETECT_ALL);
	form.getControl ("attributeList").setEnabled (enable);
}

function enabled_changed () {
	var val = form.getConfig ( "enabled" );
	var enable = false;
	if ( val != null && val.equalsIgnoreCase ("true") )
		enable = true;
	form.getControl ("uniqueAttribute").setEnabled (enable);
	form.getControl ("deltaDB").setEnabled (enable);
	form.getControl ("iterateDeletedEntries").setEnabled (enable);
	form.getControl ("removeDeletedEntries").setEnabled (enable);
	form.getControl ("returnUnchangedEntries").setEnabled (enable);
	form.getControl ("whenToCommit").setEnabled (enable);
	form.getControl ("fastAlgorithm").setEnabled (enable);
	form.getControl ("allowDuplicateDeltaKeys").setEnabled (enable);
	form.getControl ("rowLocking").setEnabled (enable);
	form.getControl ("changeDetectionMode").setEnabled (enable);
	if(enable) {
		changeDetectionMode_changed();
	} else {
		form.getControl ("attributeList").setEnabled (enable);
	}
}

changeDetectionMode_changed();
enabled_changed();

function FailOverOption_changed(){
        var val = form.getConfig ("FailOverOption");
        var enabled = false;
        if ( val != null && val.equalsIgnoreCase ("true") )
                enabled = true;
        form.setVisible("FailOverConnector", enabled);
        form.setVisible("FailBackAfter", enabled);
}
