function assemblyLine_changed() {
	var al = form.getConfigValue("assemblyLine");
	var ui = form.getControl("operationInit");
	if (al == null || al.contains("/Sequence/")) {
		ui.setEnabled(false)
	} else {
		ui.setEnabled(true);
		cfg = com.ibm.tdi.eclipse.custom.ALFC.getInitSchema(config, form);
		if ( cfg != null )
			ui.updateSchema(cfg);
	}
}

function runInBackground_changed() {
	var bg = form.getConfigValue("runInBackground");
	var background = bg != null && bg.equals("true");
	form.getControl("shareScript").setEnabled(! background);
	form.getControl("stopOnFailure").setEnabled(! background);
}

